import CoreML
import CryptoKit
import Foundation

/// CPU-only original-weight assets generated by Scripts/ModelExport/export.py.
/// Integrity checking is local, not a claim that an arbitrary manifest is signed.
public enum FixedDecoderAssets {
    private struct Manifest: Decodable {
        let schemaVersion: Int
        let minimumFrames: Int
        let maximumFrames: Int
        let shortMaximumFrames: Int
        let files: [String: String]
    }

    public static func validate(in directory: URL) throws {
        let manifest = try JSONDecoder().decode(Manifest.self, from: Data(contentsOf: directory.appendingPathComponent("decoder-manifest.json")))
        guard manifest.schemaVersion == 1, manifest.minimumFrames == 2, manifest.maximumFrames == 160,
              manifest.shortMaximumFrames == 159,
              manifest.files.keys.contains(where: { $0.hasPrefix("fixed160.mlmodelc/") }),
              manifest.files.keys.contains(where: { $0.hasPrefix("short.mlmodelc/") }) else {
            throw SynthesisError.invalidDecoderAssets
        }
        for (path, expected) in manifest.files {
            let components = path.split(separator: "/", omittingEmptySubsequences: false)
            guard components.count >= 2, ["fixed160.mlmodelc", "short.mlmodelc"].contains(String(components[0])),
                  components.allSatisfy({ !$0.isEmpty && $0 != "." && $0 != ".." }),
                  expected.count == 64 else { throw SynthesisError.invalidDecoderAssets }
            let handle = try FileHandle(forReadingFrom: directory.appendingPathComponent(path))
            defer { try? handle.close() }
            var digest = SHA256()
            while try autoreleasepool(invoking: {
                guard let data = try handle.read(upToCount: 1_048_576), !data.isEmpty else { return false }
                digest.update(data: data)
                return true
            }) { }
            let actual = digest.finalize().map { String(format: "%02x", $0) }.joined()
            guard actual == expected else { throw SynthesisError.invalidDecoderAssets }
        }
    }
}

/// Serial actor ownership through DynamicCoreMLModel. Never retains two models.
final class DecoderBackend {
    private let directory: URL
    private let fixed: Bool
    private let computeUnits: MLComputeUnits
    private var model: MLModel?
    private var loadedFrames: Int?

    init(directory: URL, computeUnits: MLComputeUnits, fixedDirectory: URL?) throws {
        if let fixedDirectory {
            try FixedDecoderAssets.validate(in: fixedDirectory)
            self.directory = fixedDirectory
            fixed = true
            self.computeUnits = .cpuOnly
        } else {
            self.directory = directory
            fixed = false
            self.computeUnits = computeUnits
        }
    }

    func prediction(from inputs: MLFeatureProvider, frames: Int) throws -> MLFeatureProvider {
        guard (1...DecoderWindow.maximumFrames).contains(frames) else { throw SynthesisError.segmentTooLong }
        guard !fixed || frames >= 2 else { throw SynthesisError.invalidAudio }
        // Even the bounded short asset can allocate per-shape workspaces. Drop
        // its prior model on shape changes instead of accumulating shape caches.
        if model == nil || (fixed && loadedFrames != frames) {
            model = nil
            loadedFrames = nil
            let name = fixed ? (frames == DecoderWindow.maximumFrames ? "fixed160" : "short") : "kokoro_backend"
            let config = MLModelConfiguration()
            config.computeUnits = computeUnits
            model = try MLModel(contentsOf: directory.appendingPathComponent("\(name).mlmodelc"), configuration: config)
            loadedFrames = frames
        }
        guard let model else { throw SynthesisError.invalidDecoderAssets }
        return try model.prediction(from: inputs)
    }
}
